mapper.select:
SELECT * FROM ${table}
WHERE deleted_at IS NULL
AND date >= #{start}
AND date <= #{end}
AND product_name = #{productName}
ORDER BY date DESC, time DESC, id DESC
LIMIT #{limit}

mapper.update:
UPDATE ${table}
SET date = #{r.date}, time = #{r.time},
    product_name = #{r.productName}, code_number = #{r.codeNumber},
    specification = #{r.specification}, type = #{r.type},
    in_quantity = #{r.inQuantity}, out_quantity = #{r.outQuantity},
    receiver = #{r.receiver}
WHERE id = #{r.id}

mapper.select:
SELECT specification, COALESCE(price, 0) AS price, type,
       (COALESCE(SUM(in_quantity), 0) - COALESCE(SUM(out_quantity), 0)) AS available
FROM ${table}
WHERE product_name = #{productName}
  AND deleted_at IS NULL

    AND code_number = #{codeNumber}



        AND (specification IS NULL OR specification = '' OR specification = 'none')


        AND specification = #{specification}


GROUP BY COALESCE(price, 0), specification
HAVING available > 0
ORDER BY price DESC
FOR UPDATE

SELECT specification, COALESCE(price, 0) AS price, type,
       (COALESCE(SUM(in_quantity), 0) - COALESCE(SUM(out_quantity), 0)) AS available
FROM ${table}
WHERE (product_name = #{productName}
       OR TRIM(REPLACE(product_name, '&amp;', '&')) = TRIM(REPLACE(#{productName}, '&amp;', '&')))
  AND deleted_at IS NULL

    AND code_number = #{codeNumber}

GROUP BY COALESCE(price, 0), specification
ORDER BY price DESC

SELECT
  COALESCE(SUM(CASE WHEN in_quantity > 0 THEN in_quantity ELSE 0 END), 0) -
  COALESCE(SUM(CASE WHEN out_quantity > 0 THEN out_quantity ELSE 0 END), 0)
FROM ${table}
WHERE (product_name = #{productName}
       OR TRIM(REPLACE(product_name, '&amp;', '&')) = TRIM(REPLACE(#{productName}, '&amp;', '&')))
  AND CAST(COALESCE(price, 0) AS DECIMAL(15,6)) = CAST(#{price} AS DECIMAL(15,6))
  AND deleted_at IS NULL

    AND code_number = #{codeNumber}

SELECT specification FROM ${table} WHERE (product_name = #{productName} OR TRIM(REPLACE(product_name, '&amp;', '&')) = TRIM(REPLACE(#{productName}, '&amp;', '&'))) AND CAST(COALESCE(price, 0) AS DECIMAL(15,6)) = CAST(#{price} AS DECIMAL(15,6)) AND deleted_at IS NULL
AND code_number = #{codeNumber}
GROUP BY specification HAVING (COALESCE(SUM(in_quantity), 0) - COALESCE(SUM(out_quantity), 0)) > 0 ORDER BY (COALESCE(SUM(in_quantity), 0) - COALESCE(SUM(out_quantity), 0)) DESC LIMIT 1

mapper.delete:
DELETE FROM ${table}
WHERE mobile_ref_id = #{refId}
  AND receiver = 'Mobile'
  AND target_system = #{system}

